window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7d993ad467a344b8"]={"versions": [{"id": "FIG-7d993ad467a344b8", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Strukturdiagramm / Metamodell-Übersichtsdiagramm im Kontext der AUTOSAR Adaptive Platform (Methodologie und Update &amp; Configuration Management / UCM). Es visualisiert die strukturelle Zusammensetzung eines Software Packages aus seinen konstituierenden Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Package</strong>: Übergeordnetes Transport- und Bereitstellungsartefakt (symbolisiert als Briefumschlag / Archivpaket).\n</li><li><strong>Software Package Manifest</strong>: Enthaltenes Metadaten- und Beschreibungsdokument (symbolisiert als Dokumentensymbol), eingebunden über eine gerichtete Aggregations-/Nesting-Beziehung («nesting») mit Kardinalität <code>1</code>.\n</li><li><strong>Software Cluster</strong>: Enthaltene Software-Artefaktkomponente (symbolisiert als Dokumentensymbol, rechts am Bildrand als „Software Cluste[r]“ abgeschnitten), eingebunden über eine gerichtete Aggregations-/Nesting-Beziehung («nesting») mit Kardinalität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert eine statische Aggregationsstruktur ohne Zeit- oder Kontrollfluss. Ein Software Package bündelt zur Verteilung und Installation auf der Adaptive Platform genau ein Software Package Manifest sowie den zugehörigen Software Cluster.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Strukturelle Vorgabe für die Paketierung von Update- und Auslieferungseinheiten (Software Packages) im UCM-Prozess der AUTOSAR Adaptive Platform. Für Entwickler und Build-Pipelines gilt, dass jedes konforme Software Package zwingend sowohl das Manifest als auch den eigentlichen Software Cluster im Paketverbund aggregieren muss.</p>"}, {"id": "FIG-dbf04a6b0b99f2c3", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Strukturdiagramm / Metamodell-Übersichtsdiagramm im Kontext der AUTOSAR Adaptive Platform (Methodologie und Update &amp; Configuration Management / UCM). Es visualisiert die strukturelle Zusammensetzung eines Software Packages aus seinen konstituierenden Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Package</strong>: Übergeordnetes Transport- und Bereitstellungsartefakt (symbolisiert als Briefumschlag / Archivpaket).\n</li><li><strong>Software Package Manifest</strong>: Enthaltenes Metadaten- und Beschreibungsdokument (symbolisiert als Dokumentensymbol), eingebunden über eine gerichtete Aggregations-/Nesting-Beziehung («nesting») mit Kardinalität <code>1</code>.\n</li><li><strong>Software Cluster</strong>: Enthaltene Software-Artefaktkomponente (symbolisiert als Dokumentensymbol, rechts am Bildrand als „Software Cluste[r]“ abgeschnitten), eingebunden über eine gerichtete Aggregations-/Nesting-Beziehung («nesting») mit Kardinalität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert eine statische Aggregationsstruktur ohne Zeit- oder Kontrollfluss. Ein Software Package bündelt zur Verteilung und Installation auf der Adaptive Platform genau ein Software Package Manifest sowie den zugehörigen Software Cluster.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Strukturelle Vorgabe für die Paketierung von Update- und Auslieferungseinheiten (Software Packages) im UCM-Prozess der AUTOSAR Adaptive Platform. Für Entwickler und Build-Pipelines gilt, dass jedes konforme Software Package zwingend sowohl das Manifest als auch den eigentlichen Software Cluster im Paketverbund aggregieren muss.</p>"}], "trans": [{"from": "FIG-7d993ad467a344b8", "to": "FIG-dbf04a6b0b99f2c3", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
